async () => {
  const res = await fetch('/api/auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username: 'admin', password: 'admin123' })
  });
  const data = await res.json();
  if (!data.token) return { ok: false, data };
  localStorage.setItem('auth-store', JSON.stringify({ state: { token: data.token, user: data.user }, version: 0 }));
  return { ok: true, user: data.user };
}

async () => {
  const store = JSON.parse(localStorage.getItem('auth-store'));
  const res = await fetch('/api/admin/users', { headers: { Authorization: 'Bearer ' + store.state.token } });
  const text = await res.text();
  return { status: res.status, body: text.slice(0, 2000) };
}

